package net.civeira.phylax.features.access.consentpurpose.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class RequiredVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property required of consent purpose ")
  void test_required_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> RequiredVO.tryFrom(null));
    Assertions.assertEquals(true, RequiredVO.from(true).isRequired());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> RequiredVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", RequiredVO.from(true).toString());
  }
}
